python - <<'PY'
import docx, sys
from docx import Document
path='/app/Graphemes_Sound_Letter_Patterns.docx'
doc=Document(path)
header_idx=None
for i,p in enumerate(doc.paragraphs):
    if p.text.startswith('Sound-Letter Pattern'):
        header_idx=i
        break
if header_idx is None:
    sys.exit('Header not found')
rows=[]
for p in doc.paragraphs[header_idx+1:]:
    txt=p.text.strip()
    if not txt:
        break
    rows.append(txt)
header_cells=[c.strip() for c in doc.paragraphs[header_idx].text.split(',')]
# Insert table at position of header
table=doc.add_table(rows=1, cols=len(header_cells))
for i,cell in enumerate(table.rows[0].cells):
    if i < len(header_cells):
        cell.text=header_cells[i]
for row in rows:
    cells=[c.strip() for c in row.split(',')]
    r=table.add_row().cells
    for i in range(min(len(cells), len(header_cells))):
        r[i].text=cells[i]
# delete old paragraphs
def del_para(p):
    p._element.getparent().remove(p._element)
for p in list(doc.paragraphs[header_idx:header_idx+1+len(rows)]):
    del_para(p)

doc.save(path)
